// spec: .qa/e2e/specs/tenders-list.md
// seed: tests/seed.hunter_free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_free.json') });

const TECH = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';
const HEALTH = 'בריאות, מדעי החיים וביוטכנולוגיה';
const ALL = 'כל התחומים';

test.describe('Field chips on /tenders — multi-select, in sync with the sidebar (#9a6100)', () => {
  test('Two chips are active together (OR), list matches the sidebar result @desktop @prod-safe #9a6100', async ({ page }) => {
    const chip = (name: string) => page.getByRole('button', { name, exact: true });
    const checkbox = (name: string) => page.getByRole('checkbox', { name, exact: true });
    const count = page.getByText(/^\d+ תוצאות$/);
    const readCount = async () => Number((await count.innerText()).match(/\d+/)![0]);

    // 1. Open /tenders — «כל התחומים» active
    await page.goto('/tenders');
    await expect(chip(ALL)).toHaveAttribute('aria-pressed', 'true');
    await expect(count).toBeVisible();

    // 2. Chip «טכנולוגיה…» → count A
    await chip(TECH).click();
    await expect(page).toHaveURL(/[?&]fields=technology(&|$)/);
    await expect(chip(TECH)).toHaveAttribute('aria-pressed', 'true');
    const a = await readCount();

    // 3. Chip «בריאות…»
    await chip(HEALTH).click();
    await expect.poll(() => decodeURIComponent(new URL(page.url()).searchParams.get('fields') ?? '').split(',').sort().join(','))
      .toBe('health,technology');

    // Expected: both chips active, «כל התחומים» not active
    await expect(chip(TECH)).toHaveAttribute('aria-pressed', 'true');
    await expect(chip(HEALTH)).toHaveAttribute('aria-pressed', 'true');
    await expect(chip(ALL)).toHaveAttribute('aria-pressed', 'false');

    // Sidebar: exactly the two checkboxes checked
    await expect(checkbox(TECH)).toBeChecked();
    await expect(checkbox(HEALTH)).toBeChecked();
    await expect(page.locator('aside input[type="checkbox"]:checked')).toHaveCount(2);

    // Count ≥ A, every card has one of the two fields (OR)
    await expect.poll(readCount).toBeGreaterThanOrEqual(a);
    const cards = page.getByRole('link', { name: /^לפרטי המכרז/ });
    await expect(cards.first()).toBeVisible();
    await expect
      .poll(async () => {
        const texts = await cards.allInnerTexts();
        const bad = texts.filter((t) => !t.includes(TECH) && !t.includes(HEALTH));
        return bad.length === 0 ? 'ok' : `cards without tech/health: ${bad.map((t) => t.slice(0, 40)).join(' | ')}`;
      })
      .toBe('ok');
  });
});
